#include <bits/stdc++.h>
using namespace std;

void solve() {
    long long n;
    cin >> n;
    
    vector<long long> a(3 * n);
    for (int i = 0; i < (3 * n); i++) {
        cin >> a[i];
    }
    
    sort(a.rbegin(), a.rend());
    
    vector<long long> prefix(3 * n + 1, 0);
    for (int i = 0; i < (3 * n); i++) prefix[i + 1] = prefix[i] + a[i];
    
    long long ans = 0;
    for (long long i = 0; i <= n; i++) {
        long long low = 0, high = n - i;
        
        while (high - low > 2) {
            long long m1 = low + (high - low) / 3;
            long long m2 = high - (high - low) / 3;
            
            long long str1 = 2 * prefix[i] + prefix[i + 2 * m1] + 3 * prefix[3 * n - 2 * i - m1];
            long long str2 = 2 * prefix[i] + prefix[i + 2 * m2] + 3 * prefix[3 * n - 2 * i - m2];
            
            if (str1 < str2) low = m1;
            else high = m2;
        }
        long long mx = 0;
        for (long long j = low; j <= high; j++) {
            long long str = 2 * prefix[i] + prefix[i + 2 * j] + 3 * prefix[3 * n - 2 * i - j];
            mx = max(mx, str);
        }
        ans = max(ans, mx);
    }
    
    cout << ans << "\n";
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	
	int t;
	cin >> t;
	for (int _i = 0; _i < t; _i++) {
	    solve();
	}
	return 0;
}
